CREATE MATERIALIZED VIEW gold.per_hour_metrics_mv TO gold.hourly_session_metrics (`hour_bucket` DateTime('UTC'), `platform` LowCardinality(String), `video_resolution` LowCardinality(String), `country` LowCardinality(String), `audio_languages` AggregateFunction(groupUniqArray, String), `subtitle_languages` AggregateFunction(groupUniqArray, String), `category` LowCardinality(String), `show_name` LowCardinality(String), `title` LowCardinality(String), `active_users_state` AggregateFunction(uniqExact, FixedString(64)), `active_session_state` AggregateFunction(uniqExact, FixedString(64))) AS SELECT toStartOfHour(minute_bucket) AS hour_bucket, platform, video_resolution, country, groupUniqArrayMergeState(audio_languages) AS audio_languages, groupUniqArrayMergeState(subtitle_languages) AS subtitle_languages, category, show_name, title, uniqExactMergeState(active_users_state) AS active_users_state, uniqExactMergeState(active_session_state) AS active_session_state FROM gold.per_minute_metrics GROUP BY hour_bucket, platform, video_resolution, country, category, show_name, title